{modal==='times'&&<>{pick('Mitarbeiter','employee',list('employees'))}{pick('Auftrag','order',list('orders').map((o:any)=>({id:o.id,name:'#'+o.number+' · '+o.title})))}{field('Datum','date','date',true)}{pick('Zeitart','type',['Produktion','Montage','Baustelle','Service','Fahrtzeit','Arbeitsvorbereitung','Lager','interne Arbeit','Pause'])}{field('Beginn','start','time',true)}{field('Ende','end','time',true)}</>}
{modal==='absences'&&<>{pick('Mitarbeiter','employee',list('employees'))}{pick('Abwesenheit','type',['Urlaub','Krankenstand','Zeitausgleich','Berufsschule','Schulung','Sonstige Abwesenheit'])}{field('Von','date','date',true)}{field('Bis','end','date',true)}<p className="form-note full">Ganztägig; Von und Bis zählen zum Zeitraum. Überschneidungen mit geplanten Einsätzen werden als Konflikt markiert.</p>{list('assignments').filter((a:any)=>!a.cancelled&&a.employee===form.employee&&a.date<=form.end&&(a.endDate||a.date)>=form.date).length>0&&<div className="warning full">Im Zeitraum sind Einsätze geplant. Die Abwesenheit kann gespeichert werden; betroffene Einteilungen werden markiert.</div>}</>}
